tasks.solution:
const rocket = {
  name: "Kartal",
  fuel: 50,
  // refuel(amount) ve status() metotlarını ekle
  refuel(amount) {
    this.fuel = Math.min(this.fuel + amount, 100);
    return this.fuel;
  },
  status() {
    return `${this.name}: yakıt ${this.fuel}`;
  },
};

console.log(rocket.refuel(30));
console.log(rocket.status());

check.js:
assert(_lines.includes("Kartal: yakıt 80"), "Çıktıda 'Kartal: yakıt 80' görünmeli.");
const before = rocket.fuel;
assert(rocket.refuel(10) === Math.min(before + 10, 100) && rocket.fuel === Math.min(before + 10, 100), "refuel(amount) yakıtı artırıp yeni değeri döndürmeli.");
assert(rocket.refuel(500) === 100 && rocket.fuel === 100, "Yakıt 100'ü geçmemeli.");
rocket.name = "Şahin";
rocket.fuel = 42;
assert(rocket.status() === "Şahin: yakıt 42", "status() adı ve yakıtı this ile okumalı ('Şahin: yakıt 42' gibi).");

