challenge.solution:
const crew = [
  { name: "Deniz", role: "pilot", hours: 120 },
  { name: "Ada", role: "mühendis", hours: 95 },
  { name: "Can", role: "doktor", hours: 60 },
  { name: "Ece", role: "pilot", hours: 150 },
];

function crewReport(list) {
  let totalHours = 0;
  const pilots = [];
  let veteran = "";
  let maxHours = -1;
  for (const { name, role, hours } of list) {
    totalHours += hours;
    if (role === "pilot") {
      pilots.push(name);
    }
    if (hours > maxHours) {
      maxHours = hours;
      veteran = name;
    }
  }
  return { totalHours, pilots, veteran };
}

console.log(crewReport(crew));

check.js:
assert(/(const|let)\s*\{[^}]+\}\s*(of|=)/.test(_code), "Parçalama kullan: for (const { name, role, hours } of list)");
const r = crewReport(crew);
assert(r && r.totalHours === 425, "crewReport(crew).totalHours 425 olmalı.");
assert(same(r.pilots, ["Deniz", "Ece"]), "crewReport(crew).pilots ['Deniz', 'Ece'] olmalı.");
assert(r.veteran === "Ece", "crewReport(crew).veteran 'Ece' olmalı.");
const r2 = crewReport([{ name: "Mert", role: "mühendis", hours: 10 }, { name: "Su", role: "pilot", hours: 30 }, { name: "Efe", role: "pilot", hours: 5 }]);
assert(r2.totalHours === 45 && same(r2.pilots, ["Su", "Efe"]) && r2.veteran === "Su", "crewReport başka bir mürettebatla da doğru çalışmalı.");

