project_task.solution:
const player = {
  name: "Kartal",
  lives: 3,
  stars: 0,
  inventory: ["kalkan"],
  collectStar() {
    this.stars++;
    return this.stars;
  },
  hit() {
    if (this.lives > 0) {
      this.lives--;
    }
    return this.lives;
  },
  status() {
    return `${this.name} | Yıldız: ${this.stars} | Can: ${this.lives}`;
  },
};

player.collectStar();
player.collectStar();
player.hit();
console.log(player.status());

check.js:
assert(typeof player.name === "string" && player.name.trim() !== "" && Array.isArray(player.inventory), "player'ın name ve inventory bilgileri korunmalı.");
assert(_lines.includes(`${player.name} | Yıldız: 2 | Can: 2`), `Çıktıda '${player.name} | Yıldız: 2 | Can: 2' görünmeli.`);
const s = player.stars;
assert(player.collectStar() === s + 1 && player.stars === s + 1, "collectStar() yıldızı 1 artırıp yeni sayıyı döndürmeli.");
player.lives = 2;
assert(player.hit() === 1 && player.lives === 1, "hit() canı 1 azaltıp kalan canı döndürmeli.");
player.hit();
player.hit();
assert(player.lives === 0 && player.hit() === 0, "Can 0'ın altına düşmemeli.");
player.name = "Nova";
player.stars = 7;
assert(player.status() === "Nova | Yıldız: 7 | Can: 0", "status() bilgileri this ile okumalı ('Nova | Yıldız: 7 | Can: 0' gibi).");

