  },
};

// astronomi hobisini ekle ve tanıtımı yazdır
profile.addHobby("astronomi");
console.log(profile.intro());

check.js:
assert(typeof profile.name === "string" && profile.name.trim() !== "" && typeof profile.age === "number", "profile'da name (metin) ve age (sayı) olmalı.");
assert(Array.isArray(profile.hobbies) && profile.hobbies.includes("astronomi"), "hobbies bir dizi olmalı ve addHobby(\"astronomi\") ile astronomi eklenmeli.");
assert(_lines.includes(profile.intro()) && /^Ben .+, \d+ yaşındayım\. Hobilerim: .*astronomi\.$/.test(profile.intro()), "intro() sonucunu yazdırmalısın: 'Ben ..., ... yaşındayım. Hobilerim: ..., astronomi.'");
const n = profile.hobbies.length;
assert(profile.addHobby("yüzme") === n + 1 && profile.hobbies[n] === "yüzme", "addHobby hobiyi sona eklemeli ve yeni hobi sayısını döndürmeli.");
profile.name = "Ada";
profile.age = 13;
profile.hobbies = ["resim", "müzik"];
assert(profile.intro() === "Ben Ada, 13 yaşındayım. Hobilerim: resim, müzik.", "intro() bilgileri this ile okumalı ('Ben Ada, 13 yaşındayım. Hobilerim: resim, müzik.' gibi).");

