project_task.solution:
// makeTask fonksiyonunu yaz
function makeTask(title, minutes = 25) {
  return { title, minutes, done: false };
}

const tasks = [];
tasks.push(makeTask("Matematik ödevi", 40));
tasks.push(makeTask("Kitap okuma"));
tasks[0].done = true;

// Görevleri for...of ile yazdır
for (const { title, minutes, done } of tasks) {
  const box = done ? "[x]" : "[ ]";
  console.log(`${box} ${title} (${minutes} dk)`);
}

check.js:
const t = makeTask("Deneme", 15);
assert(t && t.title === "Deneme" && t.minutes === 15 && t.done === false, "makeTask(\"Deneme\", 15) { title: 'Deneme', minutes: 15, done: false } döndürmeli.");
assert(makeTask("Tekrar").minutes === 25, "minutes verilmezse 25 olmalı.");
assert(makeTask("A") !== makeTask("A"), "makeTask her çağrıda yeni bir nesne döndürmeli.");
assert(tasks.length === 2 && tasks[0].done === true && tasks[1].done === false, "tasks'ta iki görev olmalı; ilki bitmiş, ikincisi bitmemiş.");
assert(_lines.join("|") === "[x] Matematik ödevi (40 dk)|[ ] Kitap okuma (25 dk)", "Çıktı '[x] Matematik ödevi (40 dk)' ve '[ ] Kitap okuma (25 dk)' olmalı.");
assert((_code.match(/console\.log/g) || []).length <= 2 && !/Kitap okuma \(/.test(_code), "Satırları elle yazma; for...of döngüsü kullan.");

