project_task.solution:
const question = {
  text: "Güneş sistemindeki en büyük gezegen hangisidir?",
  options: ["Mars", "Jüpiter", "Venüs"],
  correct: 1,
  points: 10,
  check(index) {
    return index === this.correct;
  },
  score(index) {
    return this.check(index) ? this.points : 0;
  },
};

// Soruyu ve seçenekleri yazdır
console.log(question.text);
for (let i = 0; i < question.options.length; i++) {
  console.log(`${i + 1}) ${question.options[i]}`);
}

console.log("Kazanılan puan:", question.score(1));

check.js:
assert(_lines[0] === "Güneş sistemindeki en büyük gezegen hangisidir?", "İlk satır sorunun metni olmalı.");
assert(_lines[1] === "1) Mars" && _lines[2] === "2) Jüpiter" && _lines[3] === "3) Venüs", "Seçenekler '1) Mars', '2) Jüpiter', '3) Venüs' olarak yazılmalı.");
assert(_lines.includes("Kazanılan puan: 10"), "Çıktıda 'Kazanılan puan: 10' görünmeli.");
assert((_code.match(/console\.log/g) || []).length <= 3, "Her seçenek için ayrı console.log yazma; döngü kullan.");
assert(question.check(1) === true && question.check(0) === false && question.check(2) === false, "check(1) true, check(0) ve check(2) false döndürmeli.");
question.correct = 2;
question.points = 25;
assert(question.check(2) === true && question.check(1) === false, "check() doğru sırayı this.correct'ten okumalı.");
assert(question.score(2) === 25 && question.score(0) === 0, "score(index) doğruysa this.points, yanlışsa 0 döndürmeli.");
